/// <summary>
/// designed from NDX
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args _args)
{
    switch(_args.dataset())
    {
        case tableNum(InventTable):

            if(_args.record() != null)
            {
                InventTable lInventTable = _args.record();

                NDXMagentoBase::openProductWebSite(lInventTable.NDXModelNumber);
            }
            break;
    }
}
